def test_build_watcher_doc_reference_exposes_explicit_workspace_link() -> None:
    reference = pipeline.build_watcher_doc_reference()

    assert reference["relative_path"] == "doc/watcher.md"
    assert reference["absolute_path"].endswith("doc\\watcher.md")
    assert reference["uri"].startswith("file:///")
    assert reference["uri"].endswith("/doc/watcher.md")


